              "author": "London County Council Education Department",
              "date": "September 1939",
              "context": "Every evacuated child had a cardboard label pinned to their coat lapel. The label recorded their name, school, home address, and evacuation party number, ensuring lost children could be reconnected with their teachers at rural stations. **Hinge Question:** What emotional feelings might a child experience wearing a luggage label like a parcel on a crowded train to an unknown village?",
              "hinge_question": "What emotional feelings might a child experience wearing a luggage label like a parcel on a crowded train to an unknown village?",
