              "author": "Peter Fraser / Ministry of Information & Ministry of Agriculture",
              "date": "1941",
              "context": "To replace lost food imports, the government encouraged everyone to turn gardens, parks, sports pitches, and school grounds into vegetable allotments. Over 1.4 million allotments produced millions of tons of potatoes, cabbages, and carrots. **Hinge Question:** Why was home vegetable gardening considered just as important to the war effort as building tanks and Spitfires?",
              "hinge_question": "Why was home vegetable gardening considered just as important to the war effort as building tanks and Spitfires?",
              "question_badge": "HOME PRODUCTION & PROPAGANDA",
              "question": "What did the 'Dig for Victory' poster encourage ordinary families to do?",
