          "image_alt": "Official photographic portrait of British mathematician Alan Turing at Princeton in 1936",
          "caption": "Mathematician Alan Turing (1912–1954), whose brilliant theoretical concepts and codebreaking designs at Bletchley Park played a pivotal role in cracking the complex German Enigma cipher.",
