              "image": "/units/ks2_ww2/assets/windermere_children_airlift_prague_1945.jpg",
              "title": "Source A: Child Holocaust Survivors with Chalk-Tagged Luggage at Prague Airport Airlift Departure (14 August 1945)",
              "caption": "Young concentration camp survivors with chalk numbers on their coats waiting at Prague Airport to board RAF planes for England (The '45 Aid Society / Lake District Holocaust Project).",
              "author": "Central British Fund / RAF Transport Command Photographer",
              "date": "August 1945",
              "context": "In summer 1945, philanthropist Leonard Montefiore persuaded the British Home Office to admit 1,000 orphaned child Holocaust survivors. In August 1945, the first group of 300 children—many having survived Auschwitz, Theresienstadt, and Buchenwald—were airlifted by the RAF to Cumbria. **Hinge Question:** Why was it essential to bring traumatised child survivors to a peaceful rural sanctuary like Lake Windermere rather than a crowded city hospital?",
              "hinge_question": "Why was it essential to bring traumatised child survivors to a peaceful rural sanctuary like Lake Windermere rather than a crowded city hospital?",
              "question_badge": "POST-WAR AIRLIFT & RECOVERY",
              "question": "What does Source A show about how the British helped rescue child survivors after the war?",
              "model_answer": "Source A shows young child survivors who had lost their families being carried aboard planes to fly to England. It shows that British charities acted quickly after liberation to give orphaned children safety, food, and medical care.",
