              "title": "Source C: Cover Artwork: 'After the War: From Auschwitz to Ambleside' by Tom Palmer",
              "caption": "Front cover of Tom Palmer's historical novel 'After the War', based on the true testimonies of child survivors who found sanctuary in the Lake District (Barrington Stoke, 2020).",
              "author": "Tom Palmer / Barrington Stoke",
              "date": "2020",
              "context": "Author Tom Palmer conducted in-depth research with surviving members of the '45 Aid Society—including Arek Hersh and Sir Ben Helfgott—to write his award-winning novel, introducing young readers to how children who had lost everything learned to laugh and live again by Lake Windermere. **Hinge Question:** Why is historical fiction based on real survivor testimonies a powerful way for young people today to connect with Holocaust history?",
              "hinge_question": "Why is historical fiction based on real survivor testimonies a powerful way for young people today to connect with Holocaust history?",
